package com.weearntogether.play

import android.app.Activity
import android.app.AlertDialog
import android.content.Intent
import android.graphics.Color
import android.graphics.Typeface
import android.graphics.drawable.GradientDrawable
import android.os.Bundle
import android.view.Gravity
import android.view.HapticFeedbackConstants
import android.view.View
import android.view.Window
import android.view.WindowInsets
import android.view.WindowInsetsController
import android.view.WindowManager
import android.widget.FrameLayout
import android.widget.TextView
import java.util.Locale

/** Dedicated immersive host for the native HD 2D Bubble Shooter renderer. */
class BubbleShooterActivity : Activity() {
    private lateinit var ads:NativeGameAds
    private lateinit var game:PremiumBubbleShooterView
    private lateinit var status:TextView
    private val loyalty by lazy { LoyaltyProgress(this) }
    private var dialogOpen=false
    private fun dp(v:Int)=(v*resources.displayMetrics.density).toInt()
    private fun ui(en:String,sq:String,de:String,it:String)=when(Locale.getDefault().language.lowercase(Locale.ROOT)){"sq"->sq;"de"->de;"it"->it;else->en}
    private fun chip(text:String,accent:Boolean=false,action:()->Unit)=TextView(this).apply{this.text=text;textSize=13f;setTextColor(if(accent)0xff07152c.toInt() else Color.WHITE);gravity=Gravity.CENTER;setTypeface(null,Typeface.BOLD);isClickable=true;isFocusable=true;elevation=dp(10).toFloat();background=if(accent)GradientDrawable(GradientDrawable.Orientation.TL_BR,intArrayOf(0xffffdf72.toInt(),0xffffb72f.toInt())).apply{cornerRadius=dp(23).toFloat();setStroke(dp(1),0xffffedaa.toInt())}else GradientDrawable(GradientDrawable.Orientation.TL_BR,intArrayOf(0xf0162d5b.toInt(),0xf00a72c7.toInt())).apply{cornerRadius=dp(23).toFloat();setStroke(dp(1),0x8858c8ff.toInt())};setOnClickListener{performHapticFeedback(HapticFeedbackConstants.KEYBOARD_TAP);action()}}
    private fun savedProgressLabel():String{val p=ProgressPreferences.open(this,"bubble_shooter_hd2d");val l=p.getInt("level",1).coerceIn(1,250);val b=p.getInt("best",0).coerceAtLeast(0);return ui("AUTO-SAVE • LEVEL $l/250 • BEST $b","AUTO-RUAJTJE • NIVELI $l/250 • REKORDI $b","AUTO-SPEICHERN • LEVEL $l/250 • BEST $b","SALVATAGGIO AUTO • LIVELLO $l/250 • BEST $b")}
    private fun refreshSavedProgress(){if(::status.isInitialized){status.text=savedProgressLabel();status.contentDescription=status.text}}
    private fun confirmRestart(){if(dialogOpen)return;dialogOpen=true;val d=AlertDialog.Builder(this).setTitle(ui("Restart level?","Rifillo nivelin?","Level neu starten?","Riavviare il livello?")).setMessage(ui("The current board restarts; best progress stays saved.","Tabela aktuale rifillon; rekordi mbetet i ruajtur.","Das aktuelle Feld startet neu; der Bestwert bleibt gespeichert.","La griglia riparte; il record resta salvato.")).setNegativeButton(ui("CANCEL","ANULO","ABBRECHEN","ANNULLA"),null).setPositiveButton(ui("RESTART","RIFILLO","NEUSTART","RIPROVA")){_,_->game.restart();refreshSavedProgress()}.create();d.setOnDismissListener{dialogOpen=false;refreshSavedProgress();enterImmersive()};d.show()}
    override fun onCreate(s:Bundle?){super.onCreate(s);requestWindowFeature(Window.FEATURE_NO_TITLE);window.statusBarColor=Color.TRANSPARENT;window.navigationBarColor=Color.TRANSPARENT;window.addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);enterImmersive();ads=NativeGameAds(this,"bubble");game=PremiumBubbleShooterView(this){loyalty.recordGameProgress(10);refreshSavedProgress();ads.naturalBreak()};val host=FrameLayout(this).apply{setBackgroundColor(0xff070d20.toInt());addView(game,FrameLayout.LayoutParams(-1,-1))};val header=View(this).apply{background=GradientDrawable(GradientDrawable.Orientation.TL_BR,intArrayOf(0xff0a1a3b.toInt(),0xff241050.toInt(),0xff071a38.toInt())).apply{setStroke(dp(1),0x5569cfff)}};host.addView(header,FrameLayout.LayoutParams(-1,dp(108),Gravity.TOP));host.addView(TextView(this).apply{text="BUBBLE SHOOTER HD 2D";textSize=17f;setTextColor(Color.WHITE);gravity=Gravity.CENTER;setTypeface(null,Typeface.BOLD)},FrameLayout.LayoutParams(dp(190),dp(46),Gravity.TOP or Gravity.CENTER_HORIZONTAL).apply{topMargin=dp(8)});host.addView(chip("‹  "+ui("BACK","PRAPA","ZURÜCK","INDIETRO")){finish()},FrameLayout.LayoutParams(dp(104),dp(46),Gravity.TOP or Gravity.START).apply{leftMargin=dp(12);topMargin=dp(8)});host.addView(chip("↻  "+ui("RESTART","RIFILLO","NEUSTART","RIPROVA"),true){confirmRestart()},FrameLayout.LayoutParams(dp(126),dp(46),Gravity.TOP or Gravity.END).apply{rightMargin=dp(12);topMargin=dp(8)});status=TextView(this).apply{text=savedProgressLabel();contentDescription=text;textSize=10f;setTextColor(0xffffd66b.toInt());gravity=Gravity.CENTER;setTypeface(null,Typeface.BOLD);background=GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,intArrayOf(0xdd102a54.toInt(),0xdd24164d.toInt(),0xdd0b5f9f.toInt())).apply{cornerRadius=dp(16).toFloat();setStroke(dp(1),0x88ffc857.toInt())}};host.addView(status,FrameLayout.LayoutParams(dp(300),dp(32),Gravity.TOP or Gravity.CENTER_HORIZONTAL).apply{topMargin=dp(64)});val guide=TextView(this).apply{text=ui("DRAG AIM • RELEASE • MATCH 3+","SHËNJO • LËSHO • BASHKO 3+","ZIELEN • LOSLASSEN • 3+ TREFFEN","MIRA • RILASCIA • ABBINA 3+");textSize=10f;setTextColor(0xffd9e8ff.toInt());gravity=Gravity.CENTER;setTypeface(null,Typeface.BOLD);background=GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,intArrayOf(0xdd0c244b.toInt(),0xdd2b155a.toInt(),0xdd0b477d.toInt())).apply{cornerRadius=dp(15).toFloat();setStroke(dp(1),0x6678cfff)}};host.addView(guide,FrameLayout.LayoutParams(dp(300),dp(30),Gravity.BOTTOM or Gravity.CENTER_HORIZONTAL).apply{bottomMargin=dp(132)});val rescue=chip(ui("VIDEO • RESCUE","VIDEO • NDIHMË","VIDEO • HILFE","VIDEO • AIUTO"),true){ads.rewarded(onGameplayReward={game.videoRescue();refreshSavedProgress()})};host.addView(rescue,FrameLayout.LayoutParams(dp(144),dp(42),Gravity.BOTTOM or Gravity.START).apply{leftMargin=dp(12);bottomMargin=dp(18)});val swap=TextView(this).apply{text="⇄  ●●";textSize=17f;setTextColor(0xff07152c.toInt());gravity=Gravity.CENTER;setTypeface(null,Typeface.BOLD);isClickable=true;isFocusable=true;elevation=dp(10).toFloat();background=GradientDrawable(GradientDrawable.Orientation.TL_BR,intArrayOf(0xffffdf72.toInt(),0xffffb72f.toInt())).apply{cornerRadius=dp(23).toFloat();setStroke(dp(1),0xffffedaa.toInt())};contentDescription=ui("Swap bubbles","Ndërro topat","Kugeln tauschen","Scambia bolle");setOnClickListener{performHapticFeedback(HapticFeedbackConstants.KEYBOARD_TAP);game.swapBubble()}};host.addView(swap,FrameLayout.LayoutParams(dp(88),dp(42),Gravity.BOTTOM or Gravity.CENTER_HORIZONTAL).apply{bottomMargin=dp(18)});val blocks=TextView(this).apply{text=ui("BLOCKS ›","BLLOQE ›","BLÖCKE ›","BLOCCHI ›");contentDescription=ui("Open Block Puzzle","Hap Block Puzzle","Block Puzzle öffnen","Apri Block Puzzle");textSize=10f;setTextColor(Color.WHITE);gravity=Gravity.CENTER;setTypeface(null,Typeface.BOLD);isClickable=true;isFocusable=true;elevation=dp(10).toFloat();background=GradientDrawable(GradientDrawable.Orientation.TL_BR,intArrayOf(0xff153b7a.toInt(),0xff6b2ea6.toInt(),0xffc69a32.toInt())).apply{cornerRadius=dp(23).toFloat();setStroke(dp(1),0x99ffd66b.toInt())};setOnClickListener{performHapticFeedback(HapticFeedbackConstants.KEYBOARD_TAP);startActivity(Intent(this@BubbleShooterActivity,BlockPuzzleActivity::class.java))}};host.addView(blocks,FrameLayout.LayoutParams(dp(112),dp(42),Gravity.BOTTOM or Gravity.END).apply{rightMargin=dp(12);bottomMargin=dp(18)});val blade=TextView(this).apply{text=ui("BLADE QUEST ›","THIKAT ›","BLADE QUEST ›","BLADE QUEST ›");contentDescription=ui("Open Blade Quest","Hap Blade Quest","Blade Quest öffnen","Apri Blade Quest");textSize=10f;setTextColor(Color.WHITE);gravity=Gravity.CENTER;setTypeface(null,Typeface.BOLD);isClickable=true;isFocusable=true;elevation=dp(10).toFloat();background=GradientDrawable(GradientDrawable.Orientation.TL_BR,intArrayOf(0xff162f68.toInt(),0xff5d2a92.toInt(),0xffb9872d.toInt())).apply{cornerRadius=dp(23).toFloat();setStroke(dp(1),0x88ffd66b.toInt())};setOnClickListener{performHapticFeedback(HapticFeedbackConstants.KEYBOARD_TAP);startActivity(Intent(this@BubbleShooterActivity,KnifeHitActivity::class.java))}};host.addView(blade,FrameLayout.LayoutParams(dp(112),dp(42),Gravity.BOTTOM or Gravity.END).apply{rightMargin=dp(12);bottomMargin=dp(66)});setContentView(host)}
    override fun onWindowFocusChanged(f:Boolean){super.onWindowFocusChanged(f);if(f&&!dialogOpen)enterImmersive()}
    override fun onResume(){super.onResume();if(::ads.isInitialized)ads.resume();refreshSavedProgress();if(!dialogOpen)enterImmersive()}
    private fun enterImmersive(){if(android.os.Build.VERSION.SDK_INT>=30){window.setDecorFitsSystemWindows(false);window.insetsController?.let{it.hide(WindowInsets.Type.statusBars() or WindowInsets.Type.navigationBars());it.systemBarsBehavior=WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE}}else{@Suppress("DEPRECATION") window.decorView.systemUiVisibility=View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY or View.SYSTEM_UI_FLAG_FULLSCREEN or View.SYSTEM_UI_FLAG_HIDE_NAVIGATION or View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN or View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION or View.SYSTEM_UI_FLAG_LAYOUT_STABLE}}
    override fun onPause(){if(::ads.isInitialized)ads.pause();super.onPause()}
    override fun onDestroy(){if(::ads.isInitialized)ads.destroy();super.onDestroy()}
}
